  1713		\[
  1714			\bigl( \phi_{\mathrm{A}} \, (M^{(\mathrm{Pauli},W)}_h)_{\mathrm{A}} \, \phi_{\mathrm{A}}^\dagger - (\tau^W_h)_{\mathrm{A}''} \bigr) \ket{\Delta}
  1715			= \bigl( N^W_h - (\tau^W_h)_{\mathrm{A}''} \bigr) \ket{\Delta} - N^W_h (\Id - Q_{\mathrm{A}}) \ket{\Delta}
  1716		\]
