/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
import re
import unicodedata

files = [Path('README.md'), Path('docs/QPBT-theorem-index.md')]
link_re = re.compile(r'(?<"'!!)'"\\[["'^'"\\]]*\\]\\((["'^)]+)'"\\)')

def slug(text: str) -> str:
    text = re.sub(r'"'`([''^`]*)`'"', r'\\1', text).strip().lower()
    text = unicodedata.normalize('NFKD', text)
    text = ''.join(c for c in text if not unicodedata.combining(c))
    text = re.sub(r'["'^'"\\w\\- ]', '', text, flags=re.UNICODE)
    return re.sub(r'[ -]+', '-', text).strip('-')

def anchors(path: Path):
    result = set()
    seen = {}
    for line in path.read_text(encoding='utf-8').splitlines():
        m = re.match(r'"'^(#{1,6})'"\\s+(.+?)\\s*#*"'$'"', line)
        if not m:
            continue
        base = slug(m.group(2))
        n = seen.get(base, 0)
        seen[base] = n + 1
        result.add(base if n == 0 else f'{base}-{n}')
    return result

errors = []
for source in files:
    text = source.read_text(encoding='utf-8')
    for target in link_re.findall(text):
        if target.startswith(('http://', 'https://', 'mailto:')):
            continue
        target = target.strip('<>')
        raw_path, sep, fragment = target.partition('#')
        dest = source if not raw_path else (source.parent / raw_path).resolve()
        if raw_path and not dest.exists():
            errors.append(f'{source}: missing {raw_path}')
            continue
        if fragment and dest.suffix.lower() == '.md':
            if fragment not in anchors(dest):
                errors.append(f'{source}: missing anchor {target}')
if errors:
    raise SystemExit('\\n'.join(errors))
print('Markdown local links and Markdown anchors: OK')
PY"

